WITH filtered AS (SELECT id, device_code, reading_ts, status_bits, firmware, CASE WHEN pressure >= 1016 THEN 'High' WHEN pressure >= 1004 THEN 'Medium' ELSE 'Low' END pressure_band FROM device_readings WHERE reading_ts >= DATE '2025-09-01') SELECT * FROM (SELECT firmware, device_code, status_bits FROM filtered) src PIVOT (MAX(status_bits) AS amount, COUNT(1) AS n FOR device_code IN ('DV-04' AS dv_04, 'DV-02' AS dv_02));
